// === Tab: mySketch.js ===
let scribble = new Scribble(); // global mode
let som;
let amp;
let m = 1.25;

let i = 0;
let f = 60;
let inc = 1;
let fade = 0;

function preload() {
  som = loadSound('https://openprocessing.org/sketch/1074325/files/myway_helio.mp3');
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES);

  scribble.roughness = 1; //distortion of lines

  som.play();
  amp = new p5.Amplitude();
}

function draw() {
  background(220);

  strokeWeight(3 * m);

  let vol = amp.getLevel();
  translate(width / 2, 0);
  //corpo
  push();
  randomSeed(30); //same every render step
  fill(0);
  scribble.scribbleEllipse(0, 700 * m, 360 * m, 600 * m);
  //cabeca
  translate(0, (100 - 20 * vol) * m);
  fill(255, 150, 0);
  scribble.scribbleEllipse(0, 200 * m, 200 * m, 400 * m);
  //olhos
  fill(255);
  scribble.scribbleEllipse(-45 * m, 160 * m, 20 * m, (20 - vol * 100) * m);
  scribble.scribbleEllipse(45 * m, 160 * m, 20 * m, (20 - vol * 100) * m);
  //nariz
  scribble.scribbleLine(0, 150 * m, -30 * m, 245 * m);
  scribble.scribbleLine(0, 245 * m, -30 * m, 245 * m);
  //boca
  fill(0);
  translate(-25 * m, 30 * m);
  rotate(-5);
  scribble.scribbleEllipse(0, 280 * m, 100 * m - (vol * 300) * m, (vol * 430) * m);
  pop();

  //fade
  push();
  noStroke();
  fill(0, 255 - fade);
  rect(-width / 2, 0, width, height);
  fade++;
  pop();
}
